private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder must not be null");
    }
    if (!bb.hasRemaining()) {
        throw new IllegalArgumentException("ByteBuffer has no remaining bytes");
    }
    int b0 = bb.get() & 0xFF;
    int codePoint;
    if ((b0 & 0x80) == 0) {
        // 1-byte ASCII
        codePoint = b0;
    } else if ((b0 & 0xE0) == 0xC0) {
        // 2-byte sequence
        if (bb.remaining() < 1) {
            throw new IllegalArgumentException("Incomplete 2-byte UTF-8 sequence");
        }
        int b1 = bb.get() & 0xFF;
        if ((b1 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation byte in 2-byte sequence");
        }
        codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        if (codePoint < 0x80) {
            throw new IllegalArgumentException("Overlong encoding in 2-byte sequence");
        }
    } else if ((b0 & 0xF0) == 0xE0) {
        // 3-byte sequence
        if (bb.remaining() < 2) {
            throw new IllegalArgumentException("Incomplete 3-byte UTF-8 sequence");
        }
        int b1 = bb.get() & 0xFF;
        int b2 = bb.get() & 0xFF;
        if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation byte in 3-byte sequence");
        }
        codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        if (codePoint < 0x800) {
            throw new IllegalArgumentException("Overlong encoding in 3-byte sequence");
        }
        if (codePoint >= 0xD800 && codePoint <= 0xDFFF) {
            throw new IllegalArgumentException("UTF-8 encoded surrogate half");
        }
    } else if ((b0 & 0xF8) == 0xF0) {
        // 4-byte sequence
        if (bb.remaining() < 3) {
            throw new IllegalArgumentException("Incomplete 4-byte UTF-8 sequence");
        }
        int b1 = bb.get() & 0xFF;
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation byte in 4-byte sequence");
        }
        codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        if (codePoint < 0x10000 || codePoint > 0x10FFFF) {
            throw new IllegalArgumentException("Invalid code point in 4-byte sequence");
        }
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 leading byte");
    }

    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        int cpPrime = codePoint - 0x10000;
        char high = (char) (0xD800 + (cpPrime >> 10));
        char low = (char) (0xDC00 + (cpPrime & 0x3FF));
        sb.append(high).append(low);
    }

    return i + 1;
}

