int addType(final String value){
    if (value == null) {
        throw new IllegalArgumentException("value cannot be null");
    }
    try {
        if (typeTable == null) {
            throw new IllegalStateException("typeTable is not initialized");
        }
        // Search for an existing type with the same internal class name
        for (int i = 0; i < typeTable.size(); i++) {
            TypeSymbol ts = typeTable.get(i);
            // Assuming TypeSymbol has a method getName() that returns the internal class name
            if (value.equals(ts.getName())) {
                return i;
            }
        }
        // Not found – create a new type symbol and add it to the table
        TypeSymbol newType = new TypeSymbol(value);
        typeTable.add(newType);
        return typeTable.size() - 1;
    } catch (Exception e) {
        throw new RuntimeException("Failed to add type: " + e.getMessage(), e);
    }
}

