static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be a positive long value");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    int bucketDay = 1 + ((day - 1) / dayStep) * dayStep;
    // Clamp to maximum day of month (31) to avoid invalid dates
    if (bucketDay > 31) {
        bucketDay = 31;
    }

    return year * 10000L + month * 100L + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException("index: " + index + ", len: " + len + ", str.length: " + str.length());
    }
    int size = 0;
    int end = index + len;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i++; // skip low surrogate
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

