public static String sub(String str, int start, int end) {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (start < 0) {
        start = 0;
    }
    if (end < 0) {
        end = 0;
    }
    if (start > len) {
        start = len;
    }
    if (end > len) {
        end = len;
    }
    if (start > end) {
        return "";
    }
    return str.substring(start, end);
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate arguments
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteOffset < 0) {
        throw new IllegalArgumentException("byteOffset must be non-negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset is greater than array length");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset + byteLength exceeds array length");
        }
    }

    // Ensure capacity
    int newSize = size + byteLength;
    if (data == null) {
        data = new byte[newSize];
    } else if (newSize > data.length) {
        int newCapacity = Math.max(data.length * 2, newSize);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }

    // Copy or fill
    if (byteLength > 0) {
        if (byteArrayValue != null) {
            System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
        } else {
            java.util.Arrays.fill(data, size, size + byteLength, (byte) 0);
        }
    }

    size = newSize;
    return this;
}

