private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String rawPath = u.getRawPath();
    if (rawPath == null) {
        rawPath = "";
    }
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>();
    if (rawPath.isEmpty()) {
        return result;
    }
    String[] segments = rawPath.split("/", -1);
    for (String seg : segments) {
        String value = seg;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8);
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("Invalid percent-encoding in path segment: " + seg, e);
            }
        }
        result.add(new PathSegmentImpl(value));
    }
    return result;
}

