protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Source vertex, target vertex, and edge must not be null");
    }
    // Retrieve the adjacency map for the source vertex
    java.util.Map<V, java.util.Map<V, java.util.List<E>>> index = this.index;
    java.util.Map<V, java.util.List<E>> targetMap = index.get(sourceVertex);
    if (targetMap == null) {
        targetMap = new java.util.HashMap<>();
        index.put(sourceVertex, targetMap);
    }
    // Retrieve the list of edges for the target vertex
    java.util.List<E> edgeList = targetMap.get(targetVertex);
    if (edgeList == null) {
        edgeList = new java.util.ArrayList<>();
        targetMap.put(targetVertex, edgeList);
    }
    // Add the edge to the list
    edgeList.add(e);
}

