public String format(final LoggingEvent event){
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    try {
        StringBuilder sb = new StringBuilder();
        // Timestamp
        sb.append(event.getTimeStamp());
        sb.append(' ');
        // Level
        sb.append(String.valueOf(event.getLevel()));
        sb.append(' ');
        // Thread name
        sb.append('[');
        sb.append(String.valueOf(event.getThreadName()));
        sb.append("] ");
        // Logger name
        sb.append(String.valueOf(event.getLoggerName()));
        sb.append(" - ");
        // Message
        sb.append(String.valueOf(event.getMessage()));
        // Throwable stack trace if present
        String[] throwableStrRep = event.getThrowableStrRep();
        if (throwableStrRep != null && throwableStrRep.length > 0) {
            sb.append(System.lineSeparator());
            for (String line : throwableStrRep) {
                sb.append(line);
                sb.append(System.lineSeparator());
            }
        }
        return sb.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to format LoggingEvent", e);
    }
}

