@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }

    // Null values are converted to null
    if (value == null) {
        return null;
    }

    // If already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }

    // Convert from String
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert string of length " + str.length() + " to Character");
        }
    }

    // Convert from Number (int, long, short, byte, BigInteger, BigDecimal, etc.)
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < 0 || intVal > 0xFFFF) {
            throw new Exception("Number value out of char range: " + intVal);
        }
        return (char) intVal;
    }

    // Unsupported types
    throw new Exception("Unsupported type for conversion to Character: " + value.getClass().getName());
}

