public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    int i = 0;
    while (i < len) {
        char ch = str.charAt(i);
        if (ch != '\\') {
            sb.append(ch);
            i++;
            continue;
        }
        // Count consecutive backslashes
        int backslashCount = 0;
        while (i < len && str.charAt(i) == '\\') {
            backslashCount++;
            i++;
        }
        if (i == len) {
            // Trailing backslashes
            for (int k = 0; k < backslashCount; k++) {
                sb.append('\\');
            }
            break;
        }
        // Number of literal backslashes to append
        int literalBackslashes = backslashCount / 2;
        for (int k = 0; k < literalBackslashes; k++) {
            sb.append('\\');
        }
        if (backslashCount % 2 == 0) {
            // No escape sequence, just append the next character
            sb.append(str.charAt(i));
            i++;
        } else {
            // Escape sequence
            char esc = str.charAt(i);
            i++;
            switch (esc) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 > len) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence at position " + (i - 1));
                    }
                    String hex = str.substring(i, i + 4);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex);
                    }
                    i += 4;
                    break;
                default:
                    if (esc >= '0' && esc <= '7') {
                        int octal = esc - '0';
                        int digits = 1;
                        while (digits < 3 && i < len) {
                            char c = str.charAt(i);
                            if (c >= '0' && c <= '7') {
                                octal = (octal << 3) + (c - '0');
                                i++;
                                digits++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) octal);
                    } else {
                        throw new IllegalArgumentException("Invalid escape sequence: \\" + esc);
                    }
            }
        }
    }
    return sb.toString();
}

