protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removed = 0;
    if (!root.isActive()) {
        root = null;
        return 1;
    }
    removed += removeUnusedNodesRecursive(root);
    return removed;
}

private int removeUnusedNodesRecursive(Category node) {
    int count = 0;
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }
    java.util.Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (child == null) {
            continue;
        }
        if (!child.isActive()) {
            try {
                it.remove();
            } catch (UnsupportedOperationException e) {
                throw new IllegalStateException("Cannot remove child from node: " + child, e);
            }
            count++;
        } else {
            count += removeUnusedNodesRecursive(child);
        }
    }
    return count;
}

