final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    if (constantPoolEntryIndex < 1) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be >= 1");
    }
    // constant_pool_count is stored at offset 8-9
    int constantPoolCount = ((classFileBuffer[8] & 0xFF) << 8) | (classFileBuffer[9] & 0xFF);
    if (constantPoolEntryIndex >= constantPoolCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }
    // start of constant pool entries
    int offset = 10;
    int index = 1;
    while (index < constantPoolEntryIndex) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
            case 15: // CONSTANT_MethodHandle
            case 16: // CONSTANT_MethodType
            case 17: // CONSTANT_Dynamic
            case 18: // CONSTANT_InvokeDynamic
            case 19: // CONSTANT_Module
            case 20: // CONSTANT_Package
                offset += 2;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                index++; // these take up two entries
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
        index++;
    }
    // Now at the target entry
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    offset++;
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer cannot be null");
    }
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small for UTF-8 entry");
    }
    // Decode the modified UTF-8 bytes into a String
    String result = new String(classFileBuffer, offset + 2, length, java.nio.charset.StandardCharsets.UTF_8);
    return result;
}

