private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node cannot be null");
    }
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("dir must be 1 (clockwise) or -1 (counter‑clockwise)");
    }

    try {
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

        // If the start node already satisfies the predicate or is the stop node, return it.
        Node current = circ.getNode();
        if (predicate.test(current) || current.equals(stop)) {
            return circ;
        }

        // Traverse until we find a node that satisfies the predicate or reach the stop node.
        while (true) {
            // Move to the next node in the specified direction.
            circ = (dir > 0) ? circ.next() : circ.prev();
            current = circ.getNode();

            if (predicate.test(current)) {
                return circ;
            }
            if (current.equals(stop)) {
                return circ;
            }

            // Safety check: if we loop back to the start without finding the stop node,
            // return a circulator positioned at the stop node to avoid an infinite loop.
            if (current.equals(start)) {
                return new OuterFaceCirculator(stop, dir);
            }
        }
    } catch (Exception e) {
        throw new IllegalStateException("Failed to select node on outer face", e);
    }
}

