public double vertexWeight(Set<V> v) {
    if (v == null) {
        throw new IllegalArgumentException("Vertex set cannot be null");
    }
    if (adjacencyMap == null) {
        throw new IllegalStateException("Adjacency map is not initialized");
    }
    double sum = 0.0;
    for (Map.Entry<V, Map<V, Double>> fromEntry : adjacencyMap.entrySet()) {
        Map<V, Double> toMap = fromEntry.getValue();
        if (toMap == null) {
            continue;
        }
        for (Map.Entry<V, Double> toEntry : toMap.entrySet()) {
            V toVertex = toEntry.getKey();
            if (v.contains(toVertex)) {
                Double weight = toEntry.getValue();
                if (weight != null) {
                    sum += weight;
                }
            }
        }
    }
    return sum;
}

public int compare(Object aObj1, Object aObj2) {
    // Handle reference equality first
    if (aObj1 == aObj2) {
        return 0;
    }
    // Null handling: null is considered less than any non-null object
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // Both objects are non-null. Attempt to compare if they implement Comparable
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            // The objects are not mutually comparable
            throw new IllegalArgumentException(
                "Objects are not mutually comparable: " + aObj1.getClass() + " vs " + aObj2.getClass(), e);
        }
    }
    // If we reach here, the objects cannot be compared
    throw new IllegalArgumentException(
        "Objects are not comparable: " + aObj1.getClass() + " vs " + aObj2.getClass());
}

