                    case 't':
                        sb.append('\t');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'v':
                        sb.append('\u000B'); // vertical tab
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    case 'x':
                        // \xHH: two hex digits
                        if (i + 2 >= content.length()) {
                            throw new IllegalArgumentException("Incomplete \\x escape");
                        }
                        int valX = parseHex(content, i + 1, 2);
                        sb.append((char) valX);
                        i += 2;
                        break;
                    case 'u':
                        // \uHHHH: four hex digits
                        if (i + 4 >= content.length()) {
                            throw new IllegalArgumentException("Incomplete \\u escape");
                        }
                        int valU = parseHex(content, i + 1, 4);
                        sb.append((char) valU);
                        i += 4;
                        break;
                    case 'U':
                        // \UHHHHHHHH: eight hex digits
                        if (i + 8 >= content.length()) {
                            throw new IllegalArgumentException("Incomplete \\U escape");
                        }
                        int valU8 = parseHex(content, i + 1, 8);
                        if (valU8 > 0x10FFFF) {
                            throw new IllegalArgumentException("Unicode code point out of range in \\U escape");
                        }
                        if (valU8 <= 0xFFFF) {
                            sb.append((char) valU8);
                        } else {
                            char[] surrogates = Character.toChars(valU8);
                            sb.append(surrogates[0]).append(surrogates[1]);
                        }
                        i += 8;
                        break;
                    default:
                        // Unrecognized escape: keep the character as is
                        sb.append(next);
                        break;
                }
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    } else {
        // Unquoted identifier: return as is
        return input;
    }
}

/**
 * Parses a sequence of hex digits from the given string starting at {@code start}
 * and reading {@code count} digits. Throws IllegalArgumentException if any
 * character is not a valid hex digit.
 */
private int parseHex(String s, int start, int count) {
    int value = 0;
    for (int i = 0; i < count; i++) {
        char ch = s.charAt(start + i);
        int digit = Character.digit(ch, 16);
        if (digit == -1) {
            throw new IllegalArgumentException("Invalid hex digit in escape sequence: " + ch);
        }
        value = (value << 4) | digit;
    }
    return value;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        return; // nothing to move
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return; // nothing to move
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        bucketsByLabel.set(0, target);
    }
    for (Integer v : source) {
        if (v == null || v < 0 || v >= labels.size()) {
            throw new IllegalArgumentException("vertex index out of bounds");
        }
        labels.set(v, 0);
        target.add(v);
    }
    source.clear();
}

