private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop must be non-negative");
    }
    if (elements > outputFrameStack.size()) {
        throw new IllegalStateException("Cannot pop " + elements + " elements; stack contains only " + outputFrameStack.size());
    }
    try {
        for (int i = 0; i < elements; i++) {
            outputFrameStack.removeLast();
        }
    } catch (java.util.NoSuchElementException e) {
        throw new IllegalStateException("Stack underflow while popping elements", e);
    } catch (Exception e) {
        throw new RuntimeException("Unexpected error while popping elements", e);
    }
}

