private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        throw new IllegalArgumentException("Node to unlink cannot be null");
    }
    // Verify that the node is actually part of this list
    if (node.prev != null && node.prev.next != node) {
        throw new IllegalArgumentException("Node is not part of this list (prev link mismatch)");
    }
    if (node.next != null && node.next.prev != node) {
        throw new IllegalArgumentException("Node is not part of this list (next link mismatch)");
    }

    // Update links
    if (node.prev == null) { // node is head
        this.head = node.next;
        if (this.head != null) {
            this.head.prev = null;
        } else {
            // list becomes empty
            this.tail = null;
        }
    } else if (node.next == null) { // node is tail
        this.tail = node.prev;
        if (this.tail != null) {
            this.tail.next = null;
        } else {
            // list becomes empty
            this.head = null;
        }
    } else { // node is in the middle
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    // Clean up the removed node
    node.prev = null;
    node.next = null;
    node.data = null;

    // Decrement size
    this.size--;

    return true;
}

public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> result = new ArrayList<>();
    try {
        if (currentProfiles == null || segmentSnapshot == null || searchSequence == null) {
            return result;
        }
        for (Profile profile : currentProfiles) {
            if (profile == null) continue;
            String segmentId = profile.getSegmentId();
            if (segmentId == null) continue;
            long snapshotStart = segmentSnapshot.getStart(segmentId);
            long snapshotEnd = segmentSnapshot.getEnd(segmentId);
            List<SequenceRange> ranges = searchSequence.getRangesForSegment(segmentId);
            if (ranges == null) continue;
            for (SequenceRange range : ranges) {
                if (range == null) continue;
                if (range.getStart() >= snapshotStart && range.getEnd() <= snapshotEnd) {
                    result.add(range);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error building sequence ranges", e);
    }
    return result;
}

