private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long totalSum = 0L;
    // Compute total sum and validate elements
    for (Integer val : bounds) {
        if (val == null) {
            throw new IllegalArgumentException("bounds list cannot contain null elements");
        }
        totalSum += val;
    }
    // Compute suffix sums from end to start
    long running = 0L;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffix.add(0, (int) running); // insert at front to maintain order
    }
    return new Pair<>(suffix, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array must not be null");
    }
    int len = arr.length;
    if (from < 0 || to < 0 || from >= len || to >= len) {
        throw new IndexOutOfBoundsException(
            "Indices out of bounds: from=" + from + ", to=" + to + ", length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException(
            "From index must be less than or equal to to index: from=" + from + ", to=" + to);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        return;
    }
    if (list.size == 0) {
        return;
    }
    // Grab source list's head, tail and size
    ListNodeImpl<E> srcHead = list.head;
    ListNodeImpl<E> srcTail = list.tail;
    int srcSize = list.size;

    // Detach source list
    list.head = null;
    list.tail = null;
    list.size = 0;

    // Attach to this list
    if (this.size == 0) {
        this.head = srcHead;
        this.tail = srcTail;
    } else {
        this.tail.next = srcHead;
        srcHead.prev = this.tail;
        this.tail = srcTail;
    }
    this.size += srcSize;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If the string is not null but the prefix is null, it's not a match
    if (prefix == null) {
        return false;
    }
    // If ignoreCase is true, use regionMatches with ignoreCase flag
    if (ignoreCase) {
        // regionMatches handles length checks internally
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

