        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        throw new IllegalArgumentException("typeVariable cannot be null");
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type first = bounds[0];
    if (first == null) {
        return Unknown.class;
    }
    // If the bound itself is a type variable, attempt to resolve it recursively
    if (first instanceof TypeVariable) {
        // Avoid infinite recursion if the bound refers back to the same variable
        if (first.equals(typeVariable)) {
            return Unknown.class;
        }
        @SuppressWarnings("unchecked")
        TypeVariable<?> boundVar = (TypeVariable<?>) first;
        return resolveBound(boundVar);
    }
    // For Class, ParameterizedType, WildcardType, or other Type implementations, return as is
    return first;
}

