private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> result = new ArrayList<>(keys.size());
    List<Integer> intKeys = new ArrayList<>(keys.size());
    for (K k : keys) {
        if (k == null) {
            throw new IllegalArgumentException("key cannot be null");
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("key must be Integer");
        }
        intKeys.add((Integer) k);
    }
    List<Integer> sorted = new ArrayList<>(intKeys);
    Collections.sort(sorted);
    for (Integer key : intKeys) {
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0) {
            idx = -idx - 1;
        } else {
            while (idx < sorted.size() && sorted.get(idx).equals(key)) {
                idx++;
            }
        }
        Integer upper = (idx < sorted.size()) ? sorted.get(idx) : Integer.MAX_VALUE;
        result.add(upper);
    }
    return result;
}

public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            sb.append("%7B");
        } else if (c == '}') {
            sb.append("%7D");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

