static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        if (array instanceof String[]) {
            return (String[]) array;
        } else {
            String[] result = new String[array.length];
            for (int i = 0; i < array.length; i++) {
                result[i] = (String) array[i];
            }
            return result;
        }
    }
    int newLen = array.length - nullCount;
    String[] result = new String[newLen];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    return lastDot > lastSeparator ? lastDot : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (expiredThreshold < 0) {
        throw new IllegalArgumentException("expiredThreshold must be non-negative");
    }
    if (timestamp < 0) {
        throw new IllegalArgumentException("timestamp must be non-negative");
    }
    long currentTime = System.currentTimeMillis();
    long elapsed = currentTime - timestamp;
    return elapsed > expiredThreshold;
}

