protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (message == null) {
        message = "";
    }
    if (clientWriters == null || clientWriters.isEmpty()) {
        return;
    }
    for (PrintWriter writer : clientWriters) {
        if (writer == null) {
            continue;
        }
        try {
            writer.println(message);
            writer.flush();
        } catch (Exception e) {
            error("Failed to write log to client", e);
        }
    }
}

