private String buildContentRange() {
    // Validate range boundaries
    if (start < 0 || end < start) {
        throw new IllegalArgumentException(
            "Invalid range: start=" + start + ", end=" + end);
    }

    StringBuilder sb = new StringBuilder();
    sb.append("bytes ");
    sb.append(start).append('-').append(end);
    sb.append('/');

    // If total length is known and positive, use it; otherwise use '*'
    if (totalLength > 0) {
        sb.append(totalLength);
    } else {
        sb.append('*');
    }

    return sb.toString();
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file is null");
    }
    if (!file.exists() || !file.isFile() || !file.canRead()) {
        throw new IOException("Cannot read file: " + file);
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Skip lines that cannot be parsed into a ThreadSnapshot
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            if (timeRanges == null || timeRanges.isEmpty()) {
                result.add(snapshot);
            } else {
                long ts = snapshot.getTimestamp();
                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start = range.getStartTime();
                    long end = range.getEndTime();
                    if (ts >= start && ts <= end) {
                        inRange = true;
                        break;
                    }
                }
                if (inRange) {
                    result.add(snapshot);
                }
            }
        }
    }
    return result;
}
